{
  "decline_reason": "",
  "claims": [
    {
      "text": "Section 43 requires rejection where, because of a connotation of the trade mark or a sign within it, use in relation to the particular goods or services would be likely to deceive or cause confusion.",
      "quotes": [
        {
          "ref": "TMA1995/s43",
          "quote": "An application for the registration of a trade mark in respect of particular goods or services must be rejected if, because of some connotation that the trade mark or a sign contained in the trade mark has, the use of the trade mark in relation to those goods or services would be likely to deceive or cause confusion."
        }
      ],
      "authority": "legislation"
    },
    {
      "text": "The Manual explains connotation ordinarily as something implied in a trade mark in addition to its essential or primary meaning.",
      "quotes": [
        {
          "ref": "TMM/Part29/2/2/1~1",
          "quote": "It is clear from these definitions that the word connotation refers to something implied in a trade mark, in addition to its essential or primary meaning."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For section 43, the Manual gives connotation a wider meaning that includes direct statements, not merely implications.",
      "quotes": [
        {
          "ref": "TMM/Part29/2/2/1~1",
          "quote": "In respect of section 43, connotation has a wide meaning beyond the above definitions and includes direct statements."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual explains that the relevant meaning is something other than the mark’s indication of a connection in the course of trade between the goods or services and the person applying it.",
      "quotes": [
        {
          "ref": "TMM/Part29/3#1~1",
          "quote": "the section is concerned with whether the mark the subject of the application (or a sign contained in the mark) connotes something other than a connection in the course of trade between the relevant goods or services and the person who applied (or intended to apply) it to those goods or services."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual identifies the operative test as the secondary meaning arising from reasonable consumer expectations when the meaning is considered in the context of the goods.",
      "quotes": [
        {
          "ref": "TMM/Part29/2/2/1~1",
          "quote": "The operative test is the secondary meaning which arises from the reasonable expectations of the consumer after considering the meaning in the context of the goods."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual directs examiners to consider the trade mark as a whole when identifying its potential connotation.",
      "quotes": [
        {
          "ref": "TMM/Part29/3/3/5",
          "quote": "When determining the potential connotation within a trade mark, the trade mark as a whole should be considered."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "Under the Manual’s guidance, descriptive matter does not automatically trigger section 43: there must be a real and tangible danger that consumer expectations will prove false and result in confusion.",
      "quotes": [
        {
          "ref": "TMM/Part29/2/2/1~1",
          "quote": "It does not follow that all trade marks containing descriptive matter would attract a section 43 objection. Only if there is a real and tangible danger that the consumer’s expectations may turn out to be false and result in confusion, would section 43 be triggered."
        }
      ],
      "authority": "manual"
    }
  ],
  "declined": false,
  "concepts_used": [
    "GC-0001",
    "GC-0002",
    "GC-0005",
    "GC-0008",
    "GC-0012",
    "GC-0038",
    "GC-0047",
    "GC-0168"
  ]
}
